insert into public.products (id,type,name,price,sort,data,updated_by) values
('ace','perfume','Ace',60000,10,'{"notes":["Oud","Vanilla","Cinnamon","Almonds"],"family":"Sweet oud","tags":["sweet"],"a":"#3a3a44","pair":"Vanilla & Cinnamon","story":"A fresh, sweet take on oud built with vanilla, cinnamon and almonds. Made for the evenings, and for days when you are exceptionally happy.","img":"amber"}'::jsonb,'setup'),
('arewa','perfume','Arewa',60000,20,'{"notes":["Mango","Strawberry"],"family":"Fruity","tags":["sweet","fruity"],"a":"#c2410c","pair":"Mango & Strawberry","story":"“Arewa” means beautiful one in Yoruba. A blend of mango and strawberries for people who love delicious scents, and a head-turner wherever it goes.","img":"amber"}'::jsonb,'setup'),
('asiko','perfume','Asiko',100000,30,'{"notes":["Oud","Amber","Leather","Tonka Beans"],"family":"Leather oud","tags":["new","woody"],"a":"#7a3324","pair":"Oud & Amber","story":"“Asiko” means time in Yoruba. This fragrance was curated as an encouragement to everyone in their waiting period. Your time will come.","img":"amber"}'::jsonb,'setup'),
('cherub','perfume','Cherub',100000,40,'{"notes":["Oud","Honey","Tobacco"],"family":"Honeyed oud","tags":["sweet","woody"],"a":"#8a5a1a","pair":"Honey & Tobacco","story":"Inspired by the cherubim, the four-faced angels who stand in the presence of God. Anything that close to God must carry an extraordinary aura. This is the aura of heaven.","img":"amber"}'::jsonb,'setup'),
('chocolate','perfume','Chocolate',60000,50,'{"notes":["Cocoa","Oud"],"family":"Gourmand oud","tags":["best","sweet"],"a":"#5a2614","pair":"Cocoa & Oud","story":"Born from a lifelong love of chocolate: a sexy cocoa fragrance with a tinge of oud. One of the house best sellers.","img":"amber"}'::jsonb,'setup'),
('dejavu','perfume','Dejavu',100000,60,'{"notes":["Oud","Balsam","Patchouli"],"family":"Woody","tags":["woody"],"a":"#4a3a24","pair":"Balsam & Patchouli","story":"A woody fragrance of oud, balsam and patchouli, made to mark a milestone for the house: a million dollars in perfume sold.","img":"amber"}'::jsonb,'setup'),
('desire','perfume','Desire',60000,70,'{"notes":["Vanilla","Oud","Musk"],"family":"Sweet musk","tags":["sweet"],"a":"#9a5a6a","pair":"Vanilla & Musk","story":"Created when the founder realised the house had too few sweet fragrances for women. Warm, sweet and made to leave a lasting impression.","img":"amber"}'::jsonb,'setup'),
('enigma','perfume','Enigma',60000,80,'{"notes":["Oud","Citrus","Amber","Vanilla"],"family":"Citrus amber","tags":["fresh"],"a":"#6a4a8a","pair":"Citrus & Amber","story":"When its original maker discontinued it, Sapphire Scents secured the fragrance oil and added its own signature touch. A wonder in a bottle.","img":"amber"}'::jsonb,'setup'),
('epiphany','perfume','Epiphany',75000,90,'{"notes":["Oud","Orange","Patchouli","Jasmine"],"family":"Bright floral","tags":["fresh","floral"],"a":"#c4661a","pair":"Orange & Jasmine","story":"A brainwave that stands alone in the collection. Made with very little oud, so it feels lighter and less mysterious than the rest of the house.","img":"amber"}'::jsonb,'setup'),
('goddess','perfume','Goddess',100000,100,'{"notes":["Oud","Rose","Vanilla","Jasmine"],"family":"Floral oud","tags":["floral"],"a":"#7a2350","pair":"Rose & Jasmine","story":"Every woman is a goddess. An homage to feminine beauty, allure and divinity, built on soft rose and jasmine over warm oud.","img":"amber"}'::jsonb,'setup'),
('gq','perfume','GQ',60000,110,'{"notes":["Oud","Musk"],"family":"Musky oud","tags":["woody"],"a":"#2a3a5a","pair":"Oud & Musk","story":"Made for the perfect gentleman. A tinge of oud and the presence of musk make it a favourite with men, ideal for a first date or meeting her father.","img":"amber"}'::jsonb,'setup'),
('grandeur','perfume','Grandeur',100000,120,'{"notes":["Oud","Rose","Vetiver","Jasmine"],"family":"Floral oud","tags":["best","floral"],"a":"#8c7330","pair":"Rose & Vetiver","story":"Reworked after feedback from clients and distributors to be deeper and more intense. A best seller, and one of five on every Sapphire lover’s shelf.","img":"amber"}'::jsonb,'setup'),
('ivy','perfume','Ivy',100000,130,'{"notes":["Oud","Sandalwood","Musk","Vanilla","Myrrh"],"family":"Sweet woody","tags":["woody","sweet"],"a":"#8a1d4a","pair":"Sandalwood & Myrrh","story":"The founder counts Ivy among his finest work. A sweet and woody unisex fragrance, ideal for events.","img":"amber"}'::jsonb,'setup'),
('jagaban','perfume','Jagaban',100000,140,'{"img":"jag","notes":["Incense","Mint","Cinnamon","Oud","Amber","Woody Notes"],"pyramid":{"top":["Incense","Mint"],"heart":["Cinnamon","Oud"],"base":["Amber","Woody Notes"]},"family":"Spiced oud","tags":["best","woody"],"a":"#8a4a16","pair":"Incense & Cinnamon","story":"Made to be a truly Nigerian fragrance, and the founder’s biggest surprise. A best seller, now featured on Fragrantica."}'::jsonb,'setup'),
('kadara','perfume','Kadara',100000,150,'{"notes":["Saffron","Jasmine","Oud"],"family":"Spiced floral oud","tags":["floral"],"a":"#3a5d66","pair":"Saffron & Jasmine","story":"Kadara is the Yoruba word for destiny. You don’t decide your destiny, you discover it. For men and women convinced they are on earth for a divine purpose.","img":"amber"}'::jsonb,'setup'),
('lust','perfume','Lust',100000,160,'{"notes":["Oud","Amber","Musk","Patchouli","Vanilla"],"family":"Sensual amber","tags":["sweet"],"a":"#0f4a4e","pair":"Amber & Musk","story":"The house’s most sensual fragrance, recommended for honeymoon nights and any evening you want to give your partner a special treat.","img":"amber"}'::jsonb,'setup'),
('oud-magnifique','perfume','Magnifique Oud',75000,170,'{"notes":["Oud","Musk","Rose"],"family":"Rose oud","tags":["best","floral"],"a":"#2f5157","pair":"Oud & Rose","story":"A “commercial oud”: an oud blend made to smell good to African noses while keeping its originality. One of the house’s biggest sellers.","img":"amber"}'::jsonb,'setup'),
('opulence','perfume','Opulence',100000,180,'{"notes":["Oud","Saffron","Patchouli","Musk","Rose"],"family":"Spiced rose oud","tags":["floral","woody"],"a":"#6a1a2a","pair":"Saffron & Rose","story":"One of the fragrances the house improved as its collection of rare oils grew. Rich saffron and rose over patchouli and musk.","img":"amber"}'::jsonb,'setup'),
('ruby','perfume','Ruby',60000,190,'{"notes":["Oud","Rose"],"family":"Rose oud","tags":["floral"],"a":"#b0123a","pair":"Oud & Rose","story":"A perfect marriage of oriental and French: woody and rosy, light and soft. Inspired by the founder’s first oud and rose blend, and named after his first daughter.","img":"amber"}'::jsonb,'setup'),
('saki','perfume','Saki',100000,200,'{"notes":["Frankincense","Patchouli","Sandalwood"],"family":"Resinous","tags":["woody"],"a":"#5a24b0","pair":"Frankincense & Sandalwood","story":"“Saki” means royalty, honour and favour in Yoruba. Created in the most trying period for the business, as a reminder of the grace that followed.","img":"amber"}'::jsonb,'setup'),
('salsa','perfume','Salsa',60000,210,'{"notes":["Oud","Thyme"],"family":"Aromatic oud","tags":["woody"],"a":"#5a6a2a","pair":"Oud & Thyme","story":"For nights out, weddings and birthdays. Mysterious, sweet and classy: it tells the room you deserve respect.","img":"amber"}'::jsonb,'setup'),
('sapphire-no-48','perfume','Sapphire No. 48',100000,220,'{"notes":["Oud","Milk Broom"],"family":"Soft oud","tags":["best","woody"],"a":"#3a4a7a","pair":"Oud & Milk Broom","story":"Created while preparing for a store opening. Tested on the founder’s wrist, it was still oozing after 24 hours. It became the house’s best seller.","img":"amber"}'::jsonb,'setup'),
('sapphire-no-5','perfume','Sapphire No. 5',60000,230,'{"notes":["Oud","Lemon","Jasmine"],"family":"Citrus floral oud","tags":["fresh","floral"],"a":"#b08a2a","pair":"Lemon & Jasmine","story":"The perfect fusion of oriental and French perfumery, created to suit African climates.","img":"amber"}'::jsonb,'setup'),
('sapphire-no-7','perfume','Sapphire No. 7',60000,240,'{"notes":["Oud","Ambergris","Musk"],"family":"Musky amber","tags":["woody"],"a":"#5a6a8a","pair":"Ambergris & Musk","story":"The first choice of alpha males. If success had a scent, it would be Sapphire No. 7.","img":"amber"}'::jsonb,'setup'),
('seraph','perfume','Seraph',60000,250,'{"notes":["Oud","Amber","Jasmine","Frankincense","Vanilla"],"family":"Amber resinous","tags":["woody","sweet"],"a":"#3a5fe0","pair":"Amber & Frankincense","story":"Inspired by the six-winged seraphim who stand in God’s presence. Anything that close to God should smell this good.","img":"amber"}'::jsonb,'setup'),
('siren','perfume','Siren',100000,260,'{"notes":["Bergamot","Orange","Peach","Sandalwood"],"family":"Fruity citrus","tags":["fresh","fruity"],"a":"#c4553f","pair":"Peach & Bergamot","story":"A siren is a seductive, irresistible woman: she shows up and all your worries disappear. An all-time favourite with women across Africa.","img":"amber"}'::jsonb,'setup'),
('symphony','perfume','Symphony',60000,270,'{"notes":["Oud","Balsam"],"family":"Smoky oud","tags":["woody"],"a":"#6d5590","pair":"Oud & Balsam","story":"A fine blend of oud and balsam: very smoky, very musky and irresistible, yet sweet and refreshing on every skin type.","img":"amber"}'::jsonb,'setup'),
