('i-1','diffuser','i-1 Diffuser',250000,10,'{"short":"i-1","tagline":"Smart desktop diffuser with clock and display","images":["images/diffusers/i1-desk.webp","images/diffusers/i1-front.webp"],"summary":"A compact smart aroma diffuser shaped like a classic perfume bottle. Beyond scenting the room it keeps time, wakes you with an alarm, reads the temperature and humidity, and lights the way at night with a radar-sensing night light.","body":"Choose the plug-in wall version with interchangeable plugs, or the version with a 1,200 mAh rechargeable battery that you can place anywhere. Set the working hours and scent concentration across the day from the buttons or the Bluetooth app, and infrared oil detection tells you when it is time for a refill.","features":["Button and Bluetooth app control","Smart interactive display with clock and alarm","Temperature and humidity monitoring","Radar-sensing night light","Infrared oil-level detection and leak-proof design","Custom 24-hour working time and scent concentration","Plug-in wall-mounted or 1,200 mAh rechargeable battery versions"],"specs":[["Size","91 × 70 × 140 mm"],["Oil capacity","100 ml"],["Coverage","33–100 m³ (1,177–3,531 ft³)"],["Power","4 W, DC 5 V"],["Weight","0.45 kg"],["Noise","≤ 40 dBA"],["Oil use","0.68 g per hour"],["Control","Buttons, Bluetooth app"]],"bestFor":"Bedrooms, desks, bathrooms and small offices"}'::jsonb,'setup'),
('i-3','diffuser','i-3 Diffuser',350000,20,'{"short":"i-3","tagline":"Perfume-bottle diffuser for living rooms and offices","images":["images/diffusers/i3-concrete.webp","images/diffusers/i3-lounge.webp","images/diffusers/i3-front.webp"],"summary":"Inspired by the shape of a perfume bottle, the i-3 is an elegant, minimalist diffuser for larger rooms. A high-definition display shows the time, working mode, duration and humidity, and a built-in alarm keeps your aromatic moments on schedule.","body":"Use it as a desktop piece or mount it on the wall. The wall version comes with an interchangeable socket and an anti-theft wall plate for easy, secure installation. Whether at home, in the office or at a spa, it quietly fills the space with a lasting scent.","features":["Button, Wi-Fi and Bluetooth remote control","Desktop or wall-mounted styles","High-definition display: time, mode, duration, humidity","Built-in alarm","Built-in leak-proof function","Anti-theft wall plate on the wall-mounted version"],"specs":[["Size","161 × 84 × 199 mm"],["Oil capacity","300 ml"],["Coverage","266–800 m³ (9,417–28,252 ft³)"],["Power","7.5 W, DC 5 V"],["Weight","1 kg"],["Noise","≤ 40 dBA"],["Oil use","3.93 g per hour"],["Control","Buttons, Wi-Fi, Bluetooth app"]],"bestFor":"Living rooms, offices, spas and reception areas"}'::jsonb,'setup'),
('i-5','diffuser','i-5 Diffuser',650000,30,'{"short":"i-5","tagline":"500 ml air-pump diffuser, wall or tabletop","images":["images/diffusers/i5-white.webp","images/diffusers/i5-wall-black.webp","images/diffusers/i5-parts.webp"],"summary":"A large-capacity air-pump diffuser that turns scent oil into a fine, dry mist with no water and no heat. Its 500 ml oil bottle runs for long stretches between refills, making it ideal for homes, boutiques and offices that want a constant signature scent.","body":"Mount it on the wall with the two screw holes on the back or stand it on a shelf on its fitted foot pads. Control it from the touch buttons or the mobile app over Bluetooth and dual-band Wi-Fi, with seven mist levels and seven timer settings up to 24 hours. A security lock on the atomizer cap keeps the oil in place.","features":["Waterless air-pump (cold-air) diffusion","500 ml oil bottle","Touch buttons, mobile app, Bluetooth and 2.4/5 GHz Wi-Fi","7 mist levels, from minimum to maximum","7 timer settings, up to 24 hours","Wall-mounted or tabletop, with foot pads fitted","Security lock on the atomizer cap","Black or white finish","All accessories included, with 1-year support"],"specs":[["Oil capacity","500 ml"],["Diffusion","Air pump, waterless"],["Mist levels","7"],["Timer","Min, 1, 2, 4, 8, 12 and 24 hours"],["Mounting","Wall or tabletop"],["Finish","Black or white"],["Control","Touch buttons, app, Bluetooth, Wi-Fi"],["Support","1 year"]],"bestFor":"Homes, boutiques, salons and open-plan offices"}'::jsonb,'setup'),
('f-air','diffuser','F-AIR Diffuser',700000,40,'{"short":"F-AIR","tagline":"Floor-standing fragrance machine for large spaces","images":["images/diffusers/fair-card.webp","images/diffusers/fair-lounge.webp","images/diffusers/fair-cafe.webp"],"summary":"A floor-standing fragrance machine in brushed aluminium, built to scent large spaces. Two-fluid atomization breaks the oil into an ultra-fine mist that spreads evenly through lobbies, restaurants and showrooms.","body":"Fill the 500 ml reservoir with your Sapphire scent, then manage schedules and intensity from your phone over Bluetooth and Wi-Fi, or from the remote control. It stands on a slim round base and looks at home in a lounge, a hotel lobby or a café.","features":["Two-fluid atomization for an ultra-fine mist","Covers large spaces, up to 3,000 m³","500 ml oil reservoir","Bluetooth and Wi-Fi app control, plus remote","Brushed aluminium column on a round base"],"specs":[["Type","Floor-standing"],["Oil capacity","500 ml"],["Coverage","Up to 3,000 m³"],["Diffusion","Two-fluid atomization"],["Control","Bluetooth, Wi-Fi app, remote"],["Finish","Brushed aluminium"]],"bestFor":"Hotel lobbies, restaurants, showrooms and large homes"}'::jsonb,'setup')
